import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.Bg-Zxr5O.js";const o=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Manipulating-Variables.md","filePath":"manual-zh/Manipulating-Variables.md","lastUpdated":1785684581000}'),i={name:"manual-zh/Manipulating-Variables.md"};function n(A,t,l,E,s,L){return a(),r("div",null,[...t[0]||(t[0]=[e('<h2 id="_11-manipulating-variables" tabindex="-1">11 Manipulating Variables <a class="header-anchor" href="#_11-manipulating-variables" aria-label="Permalink to &quot;11 Manipulating Variables&quot;">​</a></h2><p>数据集中的每个值都与一个_变量_相关联。变量描述这些值代表什么以及这些值的属性，例如它们应显示的格式、是数值型还是字母型，以及应如何表示缺失值。有几个实用命令用于检查和调整变量。</p><table tabindex="0"><thead><tr><th>• DISPLAY</th><th></th><th>显示关于活动数据集的信息。</th></tr></thead><tbody><tr><td>• NUMERIC</td><td></td><td>创建新的数值变量。</td></tr><tr><td>• STRING</td><td></td><td>创建新的字符串变量。</td></tr><tr><td>• RENAME VARIABLES</td><td></td><td>重命名变量。</td></tr><tr><td>• SORT VARIABLES</td><td></td><td>重新排序变量。</td></tr><tr><td>• DELETE VARIABLES</td><td></td><td>删除变量。</td></tr><tr><td>• VARIABLE LABELS</td><td></td><td>为变量设置变量标签。</td></tr><tr><td>• PRINT FORMATS</td><td></td><td>设置变量打印格式。</td></tr><tr><td>• WRITE FORMATS</td><td></td><td>设置变量写入格式。</td></tr><tr><td>• FORMATS</td><td></td><td>设置打印和写入格式。</td></tr><tr><td>• VALUE LABELS</td><td></td><td>为变量设置值标签。</td></tr><tr><td>• ADD VALUE LABELS</td><td></td><td>为变量添加值标签。</td></tr><tr><td>• MISSING VALUES</td><td></td><td>为变量设置缺失值。</td></tr><tr><td>• VARIABLE ATTRIBUTE</td><td></td><td>在变量上设置自定义属性。</td></tr><tr><td>• VARIABLE ALIGNMENT</td><td></td><td>设置显示的对齐方式。</td></tr><tr><td>• VARIABLE WIDTH</td><td></td><td>设置显示宽度。</td></tr><tr><td>• VARIABLE LEVEL</td><td></td><td>设置测量级别。</td></tr><tr><td>• VARIABLE ROLE</td><td></td><td>设置变量在分析中所扮演的角色。</td></tr><tr><td>• VECTOR</td><td></td><td>声明一个变量数组。</td></tr><tr><td>• MRSETS</td><td></td><td>添加、修改和列出多重响应集。</td></tr><tr><td>• LEAVE</td><td></td><td>不在个案之间清除变量。</td></tr></tbody></table>',3)])])}const V=d(i,[["render",n]]);export{o as __pageData,V as default};
